# logistic_maturity ----
## Setup ----
# No setup required.

## IO correctness ----
test_that("`logistic_maturity()` works with correct inputs", {
  #' @description Test that `logistic_maturity(40.5, 20.5, 0.15)` returns the logistic function of 0.15 * (40.5 - 20.5) = 3, about 0.953.
  expect_equal(
    object = FIMS:::logistic_maturity(40.5, 20.5, 0.15),
    expected = stats::plogis(3)
  )
  #' @description Test that `logistic_maturity()` returns 0.5 at the inflection point.
  expect_equal(
    object = FIMS:::logistic_maturity(2.25, 2.25, 3),
    expected = 0.5
  )
  #' @description Test that `logistic_maturity()` returns 1 value per age.
  expect_length(
    object = FIMS:::logistic_maturity(1:12, 2.25, 3),
    n = 12
  )
})

